// SCOPE GATE — fail-closed. Only the three v1 full-access role groups may use
// the assistant (ADR-005). Any unknown / missing / unmapped role → denied.
// NOTE: no $env access here — this n8n box blocks $env inside Code nodes.
// Credentials are supplied via httpRequest-node {{ $env.X }} expressions instead.
const body = $input.first().json.body || {};
const question = (body.question || '').toString().trim();

const ROLE_GROUP = {
  procurement_manager: 'procurement', head_of_procurement: 'procurement', category_manager: 'procurement',
  it: 'it', it_manager: 'it',
  user: 'user', ops_manager: 'user', requester: 'user', budget_owner: 'user',
  controlling: 'controlling',
  admin: 'admin',
  legal: 'legal'
};
const V1_ALLOWED = ['procurement', 'admin', 'controlling'];

const rawRole = (body.role || '').toString();
const group = ROLE_GROUP[rawRole] || null;
const allowed = group !== null && V1_ALLOWED.includes(group);

if (!question) {
  return [{ json: { denied: true, reason: 'empty_question', answer: 'Please ask a question about your orders, budget, suppliers, or spend.' } }];
}
if (!allowed) {
  return [{ json: { denied: true, reason: 'role_not_in_v1', role: rawRole, group,
    answer: 'The Ask assistant is being rolled out to procurement, controlling, and admin first. It will be available to your role soon.' } }];
}

const now = new Date();
const period = now.getFullYear() + '-Q' + Math.ceil((now.getMonth() + 1) / 3);
const ql = question.toLowerCase();
const supplierish = ['supplier', 'vendor', 'compliant', 'compliance', 'contract', 'expir'].some(w => ql.includes(w));
const refMatch = (question.toUpperCase().match(/TS-\d{4}-\d{3,5}/) || [])[0] || '';

return [{ json: {
  denied: false,
  question,
  role: rawRole,
  group,
  email: (body.email || '').toString(),
  branchIds: Array.isArray(body.branchIds) ? body.branchIds : [],
  costCenterId: (body.costCenterId || '').toString(),
  period,
  supplierish,
  ref: refMatch
} }];

// BUILD BUNDLE — compact, read-only TrueSpend data the assistant may use (I-9).
// Trimmed hard: full view rows blow past Claude's context, so we select only the
// fields needed to answer and rely on the precomputed rollups for spend/budget.
const rows = (nodeName) => {
  try {
    const items = $items(nodeName);
    if (!items || !items.length) return [];
    if (items.length === 1 && Array.isArray(items[0].json)) return items[0].json;
    return items.map(i => i.json).filter(v => v && typeof v === 'object' && !Array.isArray(v));
  } catch (e) { return []; }
};
const num = (v) => Number(v || 0);
const ctx = $node['Scope Gate'].json;

const openRaw      = rows('Fetch Open Tickets');
const budgetPos    = rows('Fetch Budget Positions');
const supplierRaw  = ctx.supplierish ? rows('Fetch Supplier Compliance') : [];
const expiringRaw  = ctx.supplierish ? rows('Fetch Contracts Expiring') : [];

// trim tickets to essentials
const openTickets = openRaw.slice(0, 30).map(t => ({
  reference: t.reference, title: t.title, status: t.status,
  category: t.category, value_eur: num(t.value_eur),
  supplier: t.supplier_name || t.supplier, submitted_by: t.submitted_by,
}));
const namedTicket = ctx.ref ? openTickets.filter(t => (t.reference||'').toUpperCase() === ctx.ref) : [];

// budget health derived directly from budget_positions (the command-center view
// is not readable by truespend_app). Group by branch+category with status.
const budgetHealth = budgetPos.slice(0, 80).map(b => {
  const avail = num(b.available);
  const bud = num(b.budget) || 1;
  const usedPct = (num(b.committed) + num(b.spent)) / bud;
  return { branch_id: b.branch_id, cost_center_id: b.cost_center_id, category: b.category,
    budget: num(b.budget), committed: num(b.committed), spent: num(b.spent), available: avail,
    status: usedPct >= 1 ? 'overrun' : usedPct >= 0.9 ? 'critical' : usedPct >= 0.75 ? 'warn' : 'healthy' };
});

// rollups from budget_positions (small, derived)
const spendByCategory = {};
const budgetByCostCentre = {};
for (const b of budgetPos) {
  const cat = b.category || 'unknown';
  spendByCategory[cat] = (spendByCategory[cat] || 0) + num(b.spent);
  const cc = b.cost_center_id || 'unassigned';
  if (!budgetByCostCentre[cc]) budgetByCostCentre[cc] = { budget: 0, committed: 0, spent: 0 };
  budgetByCostCentre[cc].budget    += num(b.budget);
  budgetByCostCentre[cc].committed += num(b.committed);
  budgetByCostCentre[cc].spent     += num(b.spent);
}

const supplierCompliance = supplierRaw.slice(0, 80).map(s => ({
  supplier: s.name, category: s.category, health: s.health,
  compliance: s.compliance_status, infosec: num(s.infosec_score),
  tier: s.strategic_tier, nda: s.nda_status, dpa: s.dpa_status,
}));
const contractsExpiringSoon = expiringRaw.slice(0, 40).map(c => ({
  name: c.name, supplier: c.supplier_name || c.supplier,
  expiry_date: c.expiry_date, days_to_expiry: c.days_to_expiry,
  value_eur: num(c.value_eur), auto_renew: c.auto_renew, renewal_state: c.renewal_state,
}));

const sources = [];
if (openTickets.length) sources.push('open_tickets_board');
if (namedTicket.length) sources.push('tickets:' + ctx.ref);
if (budgetHealth.length) sources.push('budget_positions');
if (Object.keys(spendByCategory).length) sources.push('budget_positions');
if (supplierCompliance.length) sources.push('suppliers');
if (contractsExpiringSoon.length) sources.push('contracts_expiring');

const bundle = {
  meta: { period: ctx.period, role: ctx.group, askedBy: ctx.email, branchScopeEnforced: false },
  question: ctx.question,
  openTickets, namedTicket, budgetHealth,
  supplierCompliance, contractsExpiringSoon,
  rollups: { spendByCategory, budgetByCostCentre },
};

const system = `You are TrueSpend's internal procurement assistant. You answer questions about orders, budget, suppliers, and spend.

HARD RULES (must follow):
1. Answer ONLY using the TrueSpend DATA provided. NEVER use outside or general knowledge.
2. If the answer is not present in the provided data, reply exactly: "I don't have that in TrueSpend." Do not guess.
3. You are read-only. Never claim to have changed, approved, ordered, or paid anything.
4. Be concise. Prefer concrete figures (EUR amounts, dates, references) straight from the data.
5. All amounts are EUR unless stated. The current period is ${ctx.period}.`;
const userMsg = `QUESTION:
${ctx.question}

TRUESPEND DATA (the ONLY source you may use):
${JSON.stringify(bundle)}

Answer using only the data above. If not answerable from it, say "I don't have that in TrueSpend."`;

return [{ json: { sources, anthropicBody: {
  model: 'claude-sonnet-4-6', max_tokens: 2048, system,
  messages: [{ role: 'user', content: userMsg }]
} } }];

// FORMAT ANSWER — extract Claude text + carry sources from Build Bundle.
const resp = $input.first().json;
const sources = $node['Build Bundle'].json.sources || [];
let answer = "I don't have that in TrueSpend.";
try {
  if (resp && Array.isArray(resp.content) && resp.content[0] && resp.content[0].text) {
    answer = resp.content[0].text.trim();
  }
} catch (e) {}
return [{ json: { answer, sources, denied: false } }];
